_object(\n      ''secret_hash'',v_client.secret_hash,''scopes'',to_jsonb(v_client.scopes),\n      ''allowed_origins'',to_jsonb(v_client.allowed_origins),''staff_onboarding_origin'',v_origin)\n  THEN RAISE EXCEPTION USING ERRCODE=''42501'',MESSAGE=''staff_onboarding_client_changed''; END IF;\n\n  SELECT * INTO v_provider FROM public.tenant_customer_identity_providers\n    WHERE id=v_provider_id AND company_id=v_company_id FOR SHARE;\n  IF NOT FOUND OR v_provider.purpose IS DISTINCT FROM ''staff'' OR NOT coalesce(v_provider.is_active,false)\n    OR v_provider.subject_claim IS DISTINCT FROM ''sub'' OR v_provider.enforcement IS DISTINCT FROM ''enforce''\n    OR p_command->''verified_provider'' IS DISTINCT FROM jsonb_build_object(\n      ''kind'',v_provider.kind,''issuer'',v_provider.issuer,''audience'',v_provider.audience,\n      ''jwks_uri'',v_provider.jwks_uri,''public_jwk'',v_provider.public_jwk,\n      ''subject_claim'',v_provider.subject_claim,''enforcement'',v_provider.enforcement)\n  THEN RAISE EXCEPTION USING ERRCODE=''42501'',MESSAGE=''staff_onboarding_provider_changed''; END IF;\n\n  SELECT lower(u.email),u.email_confirmed_at,u.deleted_at,u.banned_until\n    INTO v_email,v_auth_confirmed,v_deleted,v_banned FROM auth.users u WHERE u.id=v_user_id FOR SHARE;\n  IF NOT FOUND OR v_email IS NULL OR v_auth_confirmed IS NULL OR v_deleted IS NOT NULL\n    OR (v_banned IS NOT NULL AND v_banned>now())\n    OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=v_user_id AND user_status=''active'')\n  THEN RAISE EXCEPTION USING ERRCODE=''42501'',MESSAGE=''staff_onboarding_auth_invalid''; END IF;\n  SELECT * INTO v_invitation FROM public.company_invitations\n    WHERE id=v_invitation_id AND company_id=v_company_id FOR UPDATE;\n  IF NOT FOUND OR v_invitation.invited_user_id IS DISTINCT FROM v_user_id\n    OR lower(btrim(v_invitation.email)) IS DISTINCT FROM v_email\n    OR v_invitation.status NOT IN (''pending'',''accepted'')\n    OR (v_invitation.status=''pending'' AND (v_invitation.expires_at IS NULL OR v_invitation.expires_at<=now()))\n  THEN RAISE EXCEPTION USING ERRCODE=''42501'',MESSAGE=''staff_onboarding_invitation_invalid''; END IF;\n  SELECT request_payload INTO v_binding FROM public.canonical_command_results\n    WHERE company_id=v_company_id AND command_type=''tenant.invitation.create''\n      AND result_payload->>''invitation_id''=v_invitation_id::text FOR SHARE;\n  IF NOT FOUND OR v_binding->>''company_id'' IS DISTINCT FROM v_company_id::text\n    OR v_binding->>''channel'' IS DISTINCT FROM ''staff_api''\n    OR v_binding->>''staff_operation'' IS DISTINCT FROM ''invite''\n    OR v_binding->>''api_client_id'' IS DISTINCT FROM v_client_id::text\n  THEN RAISE EXCEPTION USING ERRCODE=''42501'',MESSAGE=''staff_onboarding_invitation_client_mismatch''; END IF;\n\n  -- Only stable canonical authority fields enter the durable request/hash.\n  -- Verification snapshots and secrets are never copied into receipts/audits.\n  RETURN public.canonical_accept_tenant_invitation(jsonb_build_object(\n    ''company_id'',v_company_id,''invitation_id'',v_invitation_id,''user_id'',v_user_id,\n    ''actor_user_id'',v_user_id,''idempotency_key'',v_key,\n    ''channel'',''staff_onboarding'',''api_client_id'',v_client_id));\nEND;\n"},{"signature":"public.gridex_decide_customer_identity_change_v1(uuid,uuid,text,text,uuid,jsonb)","before":"9a23932976decde1027eb0876ce2731c","after":"63f7ccdf09f86e5fe8f917a6560fb00e","original":"\nDECLARE\n  r public.customer_identity_change_requests%rowtype;\n  v_current text;\nBEGIN\n  IF p_outcome NOT IN (''applied'', ''rejected'', ''expired'', ''cancelled'') THEN\n    RAISE EXCEPTION ''identity_change_outcome_invalid'' USING ERRCODE = ''22023'';\n  END IF;\n  IF p_decided_by NOT IN (''customer'', ''staff'', ''system'') THEN\n    RAISE EXCEPTION ''identity_change_actor_invalid'' USING ERRCODE = ''22023'';\n  END IF;\n\n  SELECT * INTO r FROM public.customer_identity_change_requests\n   WHERE id = p_request_id AND company_id = p_company_id\n   FOR UPDATE;\n  IF r.id IS NULL THEN RAISE EXCEPTION ''identity_change_not_found'' USING ERRCODE = ''P0002''; END IF;\n\n  IF r.source_channel=''staff_api'' AND p_decided_by=''staff'' THEN\n    PERFORM public.gridex_staff_assert_write_actor_v1(r.company_id,p_actor_user_id,r.api_client_id,''customers.write'');\n  END IF;\n  IF r.status <> ''pending_customer_approval'' THEN\n    RAISE EXCEPTION ''identity_change_not_pending'' USING ERRCODE = ''55000'';\n  END IF;\n  IF p_outcome = ''applied'' AND r.approval_required AND p_decided_by <> ''customer'' THEN\n    RAISE EXCEPTION ''identity_change_requires_customer_approval'' USING ERRCODE = ''42501'';\n  END IF;\n  IF p_outcome IN (''applied'', ''rejected'') AND r.approval_required AND r.expires_at <= now() THEN\n    UPDATE public.customer_identity_change_requests SET status = ''expired'', decided_at = now(), decided_by = ''system'' WHERE id = r.id;\n    INSERT INTO public.customer_identity_change_events (company_id, customer_id, request_id, event_type, actor_kind, field, previous_value_masked, new_value_masked)\n    VALUES (r.company_id, r.customer_id, r.id, ''expired'', ''system'', r.field,\n            public.gridex_mask_identity_number(r.previous_value), public.gridex_mask_identity_number(r.new_value));\n    RETURN jsonb_build_object(''status'', ''expired'', ''request_id'', r.id);\n  END IF;\n\n  -- A takeover of binding contracts needs the new party''s explicit acceptance of exactly the\n  -- contracts and terms that were shown (same snapshot hash), each confirmation separately.\n  IF p_outcome = ''applied'' AND r.takeover_required THEN\n    IF p_acceptance IS NULL\n       OR p_acceptance->>''snapshot_sha256'' IS DISTINCT FROM r.takeover_snapshot_sha256\n       OR (p_acceptance->''confirmations''->>''identity'') IS DISTINCT FROM ''true''\n       OR (p_acceptance->''confirmations''->>''contracts'') IS DISTINCT FROM ''true''\n       OR (p_acceptance->''confirmations''->>''terms'') IS DISTINCT FROM ''true'' THEN\n      RAISE EXCEPTION ''identity_change_takeover_acceptance_required'' USING ERRCODE = ''42501'';\n    END IF;\n  END IF;\n\n  IF p_outcome = ''applied'' THEN\n    -- The value must still be what the request was based on; otherwise someone changed it meanwhile.\n    EXECUTE format(''SELECT %I FROM public.customers WHERE company_id = $1 AND id = $2 FOR UPDATE'', r.field)\n      INTO v_current USING r.company_id, r.customer_id;\n    IF v_current IS DISTINCT FROM r.previous_value THEN\n      RAISE EXCEPTION ''identity_change_stale'' USING ERRCODE = ''PT409'';\n    END IF;\n    EXECUTE format(''UPDATE public.customers SET %I = $1, updated_at = now() WHERE company_id = $2 AND id = $3'', r.field)\n      USING r.new_value, r.company_id, r.customer_id;\n  END IF;\n\n  UPDATE public.customer_identity_change_requests\n     SET status = p_outcome, decided_at = now(), decided_by = p_decided_by,\n         acceptance_evidence = CASE WHEN p_outcome = ''applied'' AND p_decided_by = ''customer'' AND p_acceptance IS NOT NULL\n                                    THEN p_acceptance || jsonb_build_object(''accepted_at'', now())\n                                    ELSE acceptance_evidence END\n   WHERE id = r.id;\n\n  IF r.approval_required AND p_outcome IN (''applied'', ''rejected'') THEN\n    INSERT INTO public.customer_identity_change_events (company_id, customer_id, request_id, event_type, actor_kind, actor_user_id, field, previous_value_masked, new_value_masked)\n    VALUES (r.company_id, r.customer_id, r.id, CASE WHEN p_outcome = ''applied'' THEN ''approved'' ELSE ''rejected'' END,\n            p_decided_by, p_actor_user_id, r.field,\n            public.gridex_mask_identity_number(r.previous_value), public.gridex_mask_identity_number(r.new_value));\n  END IF;\n  INSERT INTO public.customer_identity_change_events (company_id, customer_id, request_id, event_type, actor_kind, actor_user_id, field, previous_value_masked, new_value_masked, detail)\n  VALUES (r.company_id, r.customer_id, r.id,\n          CASE p_outcome WHEN ''applied'' THEN ''applied'' WHEN ''rejected'' THEN ''rejected'' ELSE p_outcome END,\n          p_decided_by, p_actor_user_id, r.field,\n          public.gridex_mask_identity_number(r.previous_value), public.gridex_mask_identity_number(r.new_value),\n          jsonb_build_object(''affected_contract_count'', r.affected_contract_count, ''approval_required'', r.approval_required,\n                             ''takeover_required'', r.takeover_required, ''takeover_snapshot_sha256'', r.takeover_snapshot_sha256,\n                             ''document_sha256'', r.document_sha256,\n                             ''channel'',r.source_channel,''api_client_id'',r.api_client_id,\n                             ''originating_staff_actor_user_id'',r.requested_by));\n\n  INSERT INTO public.audit_logs (company_id, actor_user_id, actor_type, system_actor, entity_type, entity_id, action,\n                                 old_values, new_values, metadata, request_id, correlation_id, resource_type, resource_id)\n  VALUES (r.company_id, p_actor_user_id,\n          CASE WHEN p_actor_user_id IS NULL THEN ''system'' ELSE ''user'' END,\n          CASE WHEN p_actor_user_id IS NULL THEN ''customer_identity_change:'' || p_decided_by ELSE NULL END,\n          ''customer'', r.customer_id::text, ''customer_identity_change_'' || p_outcome,\n          jsonb_build_object(r.field, public.gridex_mask_identity_number(r.previous_value)),\n          jsonb_build_object(r.field, public.gridex_mask_identity_number(r.new_value)),\n          jsonb_build_object(''identity_change_request_id'', r.id, ''decided_by'', p_decided_by,\n                             ''approval_required'', r.approval_required, ''affected_contract_count'', r.affected_contract_count,\n                             ''takeover_required'', r.takeover_required, ''takeover_snapshot_sha256'', r.takeover_snapshot_sha256,\n                             ''document_sha256'', r.document_sha256,\n                             ''channel'',r.source_channel,''api_client_id'',r.api_client_id,\n                             ''originating_staff_actor_user_id'',r.requested_by),\n          r.id::text, r.id::text, ''customer_identity_change_request'', r.id::text);\n\n  RETURN jsonb_build_object(''status'', p_outcome, ''request_id'', r.id, ''customer_id'', r.customer_id, ''field'', r.field);\nEND ","patched":"\nDECLARE\n  r public.customer_identity_change_requests%rowtype;\n  v_current text;\n  v_decided_at timestamptz;\nBEGIN\n  IF p_outcome NOT IN (''applied'', ''rejected'', ''expired'', ''cancelled'') THEN\n    RAISE EXCEPTION ''identity_change_outcome_invalid'' USING ERRCODE = ''22023'';\n  END IF;\n  IF p_decided_by NOT IN (''customer'', ''staff'', ''system'') THEN\n    RAISE EXCEPTION ''identity_change_actor_invalid'' USING ERRCODE = ''22023'';\n  END IF;\n\n  SELECT * INTO r FROM public.customer_identity_change_requests\n   WHERE id = p_request_id AND company_id = p_company_id\n   FOR UPDATE;\n  IF r.id IS NULL THEN RAISE EXCEPTION ''identity_change_not_found'' USING ERRCODE = ''P0002''; END IF;\n\n  IF r.source_channel=''staff_api'' AND p_decided_by=''staff'' THEN\n    PERFORM public.gridex_staff_assert_write_actor_v1(r.company_id,p_actor_user_id,r.api_client_id,''customers.write'');\n  END IF;\n  IF r.status <> ''pending_customer_approval'' THEN\n    RAISE EXCEPTION ''identity_change_not_pending'' USING ERRCODE = ''55000'';\n  END IF;\n  IF p_outcome = ''applied'' AND r.approval_required AND p_decided_by <> ''customer'' THEN\n    RAISE EXCEPTION ''identity_change_requires_customer_approval'' USING ERRCODE = ''42501'';\n  END IF;\n  v_decided_at := clock_timestamp();\n  IF p_outcome IN (''applied'', ''rejected'') AND r.approval_required AND r.expires_at <= v_decided_at THEN\n    UPDATE public.customer_identity_change_requests SET status = ''expired'', decided_at = v_decided_at, decided_by = ''system'' WHERE id = r.id;\n    INSERT INTO public.customer_identity_change_events (company_id, customer_id, request_id, event_type, actor_kind, field, previous_value_masked, new_value_masked)\n    VALUES (r.company_id, r.customer_id, r.id, ''expired'', ''system'', r.field,\n            public.gridex_mask_identity_number(r.previous_value), public.gridex_mask_identity_number(r.new_value));\n    RETURN jsonb_build_object(''status'', ''expired'', ''request_id'', r.id);\n  END IF;\n\n  -- A takeover of binding contracts needs the new party''s explicit acceptance of exactly the\n  -- contracts and terms that were shown (same snapshot hash), each confirmation separately.\n  IF p_outcome = ''applied'' AND r.takeover_required THEN\n    IF p_acceptance IS NULL\n       OR p_acceptance->>''snapshot_sha256'' IS DISTINCT FROM r.takeover_snapshot_sha256\n       OR (p_acceptance->''confirmations''->>''identity'') IS DISTINCT FROM ''true''\n       OR (p_acceptance->''confirmations''->>''contracts'') IS DISTINCT FROM ''true''\n       OR (p_acceptance->''confirmations''->>''terms'') IS DISTINCT FROM ''true'' THEN\n      RAISE EXCEPTION ''identity_change_takeover_acceptance_required'' USING ERRCODE = ''42501'';\n    END IF;\n  END IF;\n\n  IF p_outcome = ''applied'' THEN\n    -- The value must still be what the request was based on; otherwise someone changed it meanwhile.\n    EXECUTE format(''SELECT %I FROM public.customers WHERE company_id = $1 AND id = $2 FOR UPDATE'', r.field)\n      INTO v_current USING r.company_id, r.customer_id;\n    IF v_current IS DISTINCT FROM r.previous_value THEN\n      RAISE EXCEPTION ''identity_change_stale'' USING ERRCODE = ''PT409'';\n    END IF;\n    -- Revalidate the existing Staff actor/client authority after the customer lock.\n    IF r.source_channel=''staff_api'' AND p_decided_by=''staff'' THEN\n      PERFORM public.gridex_staff_assert_write_actor_v1(r.company_id,p_actor_user_id,r.api_client_id,''customers.write'');\n    END IF;\n    -- The customer lock may have waited beyond the approval deadline.\n    v_decided_at := clock_timestamp();\n    IF p_outcome IN (''applied'', ''rejected'') AND r.approval_required AND r.expires_at <= v_decided_at THEN\n      UPDATE public.customer_identity_change_requests SET status = ''expired'', decided_at = v_decided_at, decided_by = ''system'' WHERE id = r.id;\n      INSERT INTO public.customer_identity_change_events (company_id, customer_id, request_id, event_type, actor_kind, field, previous_value_masked, new_value_masked)\n      VALUES (r.company_id, r.customer_id, r.id, ''expired'', ''system'', r.field,\n              public.gridex_mask_identity_number(r.previous_value), public.gridex_mask_identity_number(r.new_value));\n      RETURN jsonb_build_object(''status'', ''expired'', ''request_id'', r.id);\n    END IF;\n    EXECUTE format(''UPDATE public.customers SET %I = $1, updated_at = now() WHERE company_id = $2 AND id = $3'', r.field)\n      USING r.new_value, r.company_id, r.customer_id;\n  END IF;\n\n  UPDATE public.customer_identity_change_requests\n     SET status = p_outcome, decided_at = v_decided_at, decided_by = p_decided_by,\n         acceptance_evidence = CASE WHEN p_outcome = ''applied'' AND p_decided_by = ''customer'' AND p_acceptance IS NOT NULL\n                                    THEN p_acceptance || jsonb_build_object(''accepted_at'', v_decided_at)\n                                    ELSE acceptance_evidence END\n   WHERE id = r.id;\n\n  IF r.approval_required AND p_outcome IN (''applied'', ''rejected'') THEN\n    INSERT INTO public.customer_identity_change_events (company_id, customer_id, request_id, event_type, actor_kind, actor_user_id, field, previous_value_masked, new_value_masked)\n    VALUES (r.company_id, r.customer_id, r.id, CASE WHEN p_outcome = ''applied'' THEN ''approved'' ELSE ''rejected'' END,\n            p_decided_by, p_actor_user_id, r.field,\n            public.gridex_mask_identity_number(r.previous_value), public.gridex_mask_identity_number(r.new_value));\n  END IF;\n  INSERT INTO public.customer_identity_change_events (company_id, customer_id, request_id, event_type, actor_kind, actor_user_id, field, previous_value_masked, new_value_masked, detail)\n  VALUES (r.company_id, r.customer_id, r.id,\n          CASE p_outcome WHEN ''applied'' THEN ''applied'' WHEN ''rejected'' THEN ''rejected'' ELSE p_outcome END,\n          p_decided_by, p_actor_user_id, r.field,\n          public.gridex_mask_identity_number(r.previous_value), public.gridex_mask_identity_number(r.new_value),\n          jsonb_build_object(''affected_contract_count'', r.affected_contract_count, ''approval_required'', r.approval_required,\n                             ''takeover_required'', r.takeover_required, ''takeover_snapshot_sha256'', r.takeover_snapshot_sha256,\n                             ''document_sha256'', r.document_sha256,\n                             ''channel'',r.source_channel,''api_client_id'',r.api_client_id,\n                             ''originating_staff_actor_user_id'',r.requested_by));\n\n  INSERT INTO public.audit_logs (company_id, actor_user_id, actor_type, system_actor, entity_type, entity_id, action,\n                                 old_values, new_values, metadata, request_id, correlation_id, resource_type, resource_id)\n  VALUES (r.company_id, p_actor_user_id,\n          CASE WHEN p_actor_user_id IS NULL THEN ''system'' ELSE ''user'' END,\n          CASE WHEN p_actor_user_id IS NULL THEN ''customer_identity_change:'' || p_decided_by ELSE NULL END,\n          ''customer'', r.customer_id::text, ''customer_identity_change_'' || p_outcome,\n          jsonb_build_object(r.field, public.gridex_mask_identity_number(r.previous_value)),\n          jsonb_build_object(r.field, public.gridex_mask_identity_number(r.new_value)),\n          jsonb_build_object(''identity_change_request_id'', r.id, ''decided_by'', p_decided_by,\n                             ''approval_required'', r.approval_required, ''affected_contract_count'', r.affected_contract_count,\n                             ''takeover_required'', r.takeover_required, ''takeover_snapshot_sha256'', r.takeover_snapshot_sha256,\n                             ''document_sha256'', r.document_sha256,\n                             ''channel'',r.source_channel,''api_client_id'',r.api_client_id,\n                             ''originating_staff_actor_user_id'',r.requested_by),\n          r.id::text, r.id::text, ''customer_identity_change_request'', r.id::text);\n\n  RETURN jsonb_build_object(''status'', p_outcome, ''request_id'', r.id, ''customer_id'', r.customer_id, ''field'', r.field);\nEND ","expected":{"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proconfig":["search_path=pg_catalog"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":["p_company_id","p_request_id","p_outcome","p_decided_by","p_actor_user_id","p_acceptance"],"proargmodes":null,"return_type":"jsonb","identity_arguments":"p_company_id uuid, p_request_id uuid, p_outcome text, p_decided_by text, p_actor_user_id uuid, p_acceptance jsonb","arguments":"p_company_id uuid, p_request_id uuid, p_outcome text, p_decided_by text, p_actor_user_id uuid DEFAULT NULL::uuid, p_acceptance jsonb DEFAULT NULL::jsonb","language":"plpgsql"}},{"signature":"public.canonical_accept_tenant_invitation(jsonb)","before":"5e7710d3653185c9c6307cc06d197a0a","after":"84da220e65ca1a019bdf55b33fa1664c","original":"\ndeclare\n  v_actor_user_id uuid := nullif(p_command->>''actor_user_id'','''')::uuid;\n  v_user_id uuid := nullif(p_command->>''user_id'','''')::uuid;\n  v_invitation_id uuid := nullif(p_command->>''invitation_id'','''')::uuid;\n  v_idempotency_key text := nullif(btrim(p_command->>''idempotency_key''),'''');\n  v_invitation public.company_invitations%rowtype;\n  v_company_status text;\n  v_auth_email text;\n  v_profile_active boolean;\n  v_role_key text;\n  v_membership_role text;\n  v_role_id uuid;\n  v_existing_user_role_id uuid;\n  v_request jsonb := p_command - ''actor_user_id'';\n  v_hash text;\n  v_existing public.canonical_command_results%rowtype;\n  v_result jsonb;\n  v_event_id uuid;\nbegin\n  if v_actor_user_id is null or v_user_id is null or v_actor_user_id<>v_user_id\n     or v_invitation_id is null or v_idempotency_key is null then\n    raise exception using errcode=''22023'', message=''verified_user_invitation_and_idempotency_required'';\n  end if;\n\n  select * into v_invitation\n  from public.company_invitations\n  where id=v_invitation_id\n  for update;\n  if not found then\n    raise exception using errcode=''P0002'', message=''tenant_invitation_not_found'';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(''tenant-invitation:''||v_invitation.company_id::text||'':''||v_invitation_id::text,0));\n  v_hash := public.canonical_json_sha256(v_request);\n\n  select * into v_existing\n  from public.canonical_command_results\n  where company_id=v_invitation.company_id\n    and command_type=''tenant.invitation.accept''\n    and idempotency_key=v_idempotency_key;\n  if found then\n    if v_existing.request_hash is distinct from v_hash then\n      raise exception using errcode=''23505'', message=''IDEMPOTENCY_KEY_REUSE_MISMATCH'';\n    end if;\n    return v_existing.result_payload;\n  end if;\n\n  if coalesce(v_invitation.status,'''')=''accepted''\n     and v_invitation.invited_user_id=v_user_id then\n    v_result:=jsonb_build_object(\n      ''changed'',false,''already_accepted'',true,''company_id'',v_invitation.company_id,\n      ''user_id'',v_user_id,''invitation_id'',v_invitation_id\n    );\n    insert into public.canonical_command_results(\n      company_id,command_type,idempotency_key,request_hash,request_payload,result_payload,actor_user_id\n    ) values(\n      v_invitation.company_id,''tenant.invitation.accept'',v_idempotency_key,v_hash,v_request,v_result,v_actor_user_id\n    );\n    return v_result;\n  end if;\n\n  if coalesce(v_invitation.status,'''')<>''pending'' then\n    raise exception using errcode=''23514'', message=''tenant_invitation_not_pending'';\n  end if;\n  if v_invitation.expires_at is not null and v_invitation.expires_at<=now() then\n    raise exception using errcode=''23514'', message=''tenant_invitation_expired'';\n  end if;\n  if v_invitation.invited_user_id is not null and v_invitation.invited_user_id<>v_user_id then\n    raise exception using errcode=''42501'', message=''tenant_invitation_user_mismatch'';\n  end if;\n\n  select coalesce(lower(u.email),public.gridex_staff_anchor_invitation_email_v1(v_invitation.id,v_invitation.company_id,u.id)),\n         exists(select 1 from public.user_profiles up where up.id=u.id and up.user_status=''active'')\n    into v_auth_email,v_profile_active\n  from auth.users u\n  where u.id=v_user_id and u.deleted_at is null\n    and (u.banned_until is null or u.banned_until<=now());\n  if v_auth_email is null or not coalesce(v_profile_active,false) then\n    raise exception using errcode=''42501'', message=''target_auth_user_missing_or_inactive'';\n  end if;\n  if v_auth_email<>lower(coalesce(v_invitation.email,v_invitation.invited_email,'''')) then\n    raise exception using errcode=''42501'', message=''tenant_invitation_email_mismatch'';\n  end if;\n\n  select status into v_company_status\n  from public.companies where id=v_invitation.company_id for update;\n  if v_company_status not in (''onboarding'',''active'') then\n    raise exception using errcode=''23514'', message=''tenant_state_blocks_invitation_acceptance'';\n  end if;\n\n  v_role_key:=lower(coalesce(nullif(v_invitation.role_key,''''),''customer_service_agent''));\n  select m.membership_role into v_membership_role\n  from public.canonical_tenant_access_role_mapping m\n  where m.role_key=v_role_key and m.is_assignable;\n  if v_membership_role is null then\n    raise exception using errcode=''22023'', message=''canonical_tenant_role_not_assignable'';\n  end if;\n  if nullif(lower(v_invitation.membership_role),'''') is not null\n     and lower(v_invitation.membership_role)<>v_membership_role then\n    raise exception using errcode=''23514'', message=''invitation_membership_role_role_key_mismatch'';\n  end if;\n\n  select r.id into v_role_id\n  from public.roles r\n  where lower(coalesce(r.key,r.name))=v_role_key\n  order by r.created_at asc,r.id asc\n  limit 1;\n  if v_role_id is null then\n    raise exception using errcode=''22023'', message=''canonical_tenant_role_definition_missing'';\n  end if;\n\n  insert into public.company_memberships(\n    company_id,user_id,membership_role,role_key,status,is_active,invited_email,\n    invited_by,invited_at,accepted_at,disabled_at,removed_at,status_reason,metadata\n  ) values(\n    v_invitation.company_id,v_user_id,v_membership_role,v_role_key,''active'',true,v_auth_email,\n    v_invitation.invited_by,coalesce(v_invitation.created_at,now()),now(),null,null,null,\n    jsonb_build_object(''canonical_invitation_id'',v_invitation_id,''canonical_access_command'',v_idempotency_key)\n  ) on conflict(company_id,user_id) do update set\n    membership_role=excluded.membership_role,role_key=excluded.role_key,status=''active'',is_active=true,\n    invited_email=excluded.invited_email,accepted_at=coalesce(public.company_memberships.accepted_at,now()),\n    disabled_at=null,removed_at=null,status_reason=null,\n    metadata=coalesce(public.company_memberships.metadata,''{}''::jsonb)||excluded.metadata,\n    updated_at=now();\n\n  update public.user_roles\n  set status=''disabled'',is_active=false,updated_at=now()\n  where company_id=v_invitation.company_id and user_id=v_user_id and coalesce(is_active,true);\n\n  select ur.id into v_existing_user_role_id\n  from public.user_roles ur\n  where ur.company_id=v_invitation.company_id and ur.user_id=v_user_id and ur.role_id=v_role_id\n  order by ur.created_at asc,ur.id asc\n  limit 1\n  for update;\n  if v_existing_user_role_id is null then\n    insert into public.user_roles(user_id,company_id,role,role_id,status,is_activ