; i public.company_invitations%rowtype;\nBEGIN\n result:=public.gridex_lookup_pending_staff_identity_binding_v1(p_command);\n IF result->>''binding_id'' IS DISTINCT FROM p_command->>''binding_id'' OR result->>''binding_version'' IS DISTINCT FROM p_command->>''binding_version''\n  OR p_command->''email_confirmed'' IS DISTINCT FROM ''true''::jsonb\n THEN RAISE EXCEPTION ''staff_identity_acceptance_invalid'' USING ERRCODE=''42501''; END IF;\n SELECT * INTO b FROM public.tenant_staff_identity_bindings WHERE id=(result->>''binding_id'')::uuid FOR UPDATE;\n SELECT * INTO i FROM public.company_invitations WHERE id=b.invitation_id;\n IF lower(btrim(p_command->>''verified_email'')) IS DISTINCT FROM lower(btrim(i.email)) OR i.invited_user_id IS DISTINCT FROM b.actor_user_id\n  OR nullif(btrim(p_command->>''idempotency_key''),'''') IS NULL\n THEN RAISE EXCEPTION ''staff_identity_acceptance_invalid'' USING ERRCODE=''42501''; END IF;\n PERFORM 1 FROM auth.users u JOIN public.user_profiles profile ON profile.id=u.id WHERE u.id=b.actor_user_id FOR SHARE OF u,profile;\n IF NOT FOUND OR NOT EXISTS(SELECT FROM auth.users u JOIN public.user_profiles profile ON profile.id=u.id WHERE u.id=b.actor_user_id AND u.deleted_at IS NULL\n  AND (u.banned_until IS NULL OR u.banned_until<=clock_timestamp()) AND profile.user_status=''active'')\n THEN RAISE EXCEPTION ''staff_identity_actor_inactive'' USING ERRCODE=''42501''; END IF;\n IF b.status=''pending'' THEN UPDATE public.tenant_staff_identity_bindings SET status=''active'' WHERE id=b.id; END IF;\n RETURN public.canonical_accept_tenant_invitation(jsonb_build_object(''company_id'',b.company_id,''invitation_id'',b.invitation_id,''user_id'',b.actor_user_id,''actor_user_id'',b.actor_user_id,\n   ''api_client_id'',b.api_client_id,''channel'',''staff_external_onboarding'',''idempotency_key'',p_command->>''idempotency_key''));\nEND ","patched":"\nDECLARE result jsonb; b public.tenant_staff_identity_bindings%rowtype; i public.company_invitations%rowtype;\nBEGIN\n result:=public.gridex_lookup_pending_staff_identity_binding_v1(p_command);\n IF result->>''binding_id'' IS DISTINCT FROM p_command->>''binding_id'' OR result->>''binding_version'' IS DISTINCT FROM p_command->>''binding_version''\n  OR p_command->''email_confirmed'' IS DISTINCT FROM ''true''::jsonb\n THEN RAISE EXCEPTION ''staff_identity_acceptance_invalid'' USING ERRCODE=''42501''; END IF;\n SELECT * INTO b FROM public.tenant_staff_identity_bindings WHERE id=(result->>''binding_id'')::uuid FOR UPDATE;\n SELECT * INTO i FROM public.company_invitations WHERE id=b.invitation_id;\n IF lower(btrim(p_command->>''verified_email'')) IS DISTINCT FROM lower(btrim(i.email)) OR i.invited_user_id IS DISTINCT FROM b.actor_user_id\n  OR nullif(btrim(p_command->>''idempotency_key''),'''') IS NULL\n THEN RAISE EXCEPTION ''staff_identity_acceptance_invalid'' USING ERRCODE=''42501''; END IF;\n PERFORM 1 FROM auth.users u JOIN public.user_profiles profile ON profile.id=u.id WHERE u.id=b.actor_user_id FOR SHARE OF u,profile;\n IF NOT FOUND OR NOT EXISTS(SELECT FROM auth.users u JOIN public.user_profiles profile ON profile.id=u.id WHERE u.id=b.actor_user_id AND u.deleted_at IS NULL\n  AND (u.banned_until IS NULL OR u.banned_until<=clock_timestamp()) AND profile.user_status=''active'')\n THEN RAISE EXCEPTION ''staff_identity_actor_inactive'' USING ERRCODE=''42501''; END IF;\n -- All registration/invitation locks are already held; refresh time after Auth/binding waits.\n PERFORM public.gridex_staff_identity_registration_v1(p_command,true);\n PERFORM public.gridex_staff_identity_invitation_v1(p_command,false);\n IF b.status=''pending'' THEN UPDATE public.tenant_staff_identity_bindings SET status=''active'' WHERE id=b.id; END IF;\n result:=public.canonical_accept_tenant_invitation(jsonb_build_object(''company_id'',b.company_id,''invitation_id'',b.invitation_id,''user_id'',b.actor_user_id,''actor_user_id'',b.actor_user_id,\n   ''api_client_id'',b.api_client_id,''channel'',''staff_external_onboarding'',''idempotency_key'',p_command->>''idempotency_key''));\n -- A wait inside canonical acceptance must not admit an expired client/invitation.\n PERFORM public.gridex_staff_identity_registration_v1(p_command,true);\n PERFORM public.gridex_staff_identity_invitation_v1(p_command,false);\n RETURN result;\nEND ","expected":{"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proconfig":["search_path=pg_catalog"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":["p_command"],"proargmodes":null,"return_type":"jsonb","identity_arguments":"p_command jsonb","arguments":"p_command jsonb","language":"plpgsql"},"canonicalBefore":"8bce4c7e18ff33066b80eb5073307a01","canonicalOriginal":"\nDECLARE result jsonb; b public.tenant_staff_identity_bindings%rowtype; i public.company_invitations%rowtype;\nBEGIN\n result:=public.gridex_lookup_pending_staff_identity_binding_v1(p_command);\n IF result->>''binding_id'' IS DISTINCT FROM p_command->>''binding_id'' OR result->>''binding_version'' IS DISTINCT FROM p_command->>''binding_version''\n  OR p_command->''email_confirmed'' IS DISTINCT FROM ''true''::jsonb\n THEN RAISE EXCEPTION ''staff_identity_acceptance_invalid'' USING ERRCODE=''42501''; END IF;\n SELECT * INTO b FROM public.tenant_staff_identity_bindings WHERE id=(result->>''binding_id'')::uuid FOR UPDATE;\n SELECT * INTO i FROM public.company_invitations WHERE id=b.invitation_id;\n IF lower(btrim(p_command->>''verified_email'')) IS DISTINCT FROM lower(btrim(i.email)) OR i.invited_user_id IS DISTINCT FROM b.actor_user_id\n  OR nullif(btrim(p_command->>''idempotency_key''),'''') IS NULL\n THEN RAISE EXCEPTION ''staff_identity_acceptance_invalid'' USING ERRCODE=''42501''; END IF;\n PERFORM 1 FROM auth.users u JOIN public.user_profiles profile ON profile.id=u.id WHERE u.id=b.actor_user_id FOR SHARE OF u,profile;\n IF NOT FOUND OR NOT EXISTS(SELECT FROM auth.users u JOIN public.user_profiles profile ON profile.id=u.id WHERE u.id=b.actor_user_id AND u.deleted_at IS NULL\n  AND (u.banned_until IS NULL OR u.banned_until<=clock_timestamp()) AND profile.user_status=''active'')\n THEN RAISE EXCEPTION ''staff_identity_actor_inactive'' USING ERRCODE=''42501''; END IF;\n IF b.status=''pending'' THEN UPDATE public.tenant_staff_identity_bindings SET status=''active'' WHERE id=b.id; END IF;\n -- Stable authority only. No tenant access token, password or verification\n -- snapshot enters the unchanged command hash, audit or membership engine.\n RETURN public.canonical_accept_tenant_invitation(jsonb_build_object(''company_id'',b.company_id,''invitation_id'',b.invitation_id,''user_id'',b.actor_user_id,''actor_user_id'',b.actor_user_id,\n   ''api_client_id'',b.api_client_id,''channel'',''staff_external_onboarding'',''idempotency_key'',p_command->>''idempotency_key''));\nEND "}]'::jsonb;
BEGIN
 FOR spec IN SELECT value FROM jsonb_array_elements(config) LOOP
  SELECT * INTO before_function FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(spec->>'signature');
  IF NOT FOUND THEN RAISE EXCEPTION 'auth_expiry_existing_core_required: %',spec->>'signature'; END IF;
  SELECT jsonb_build_object('owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,
   'proconfig',p.proconfig,'provolatile',p.provolatile,'prosecdef',p.prosecdef,
   'proisstrict',p.proisstrict,'proleakproof',p.proleakproof,'proparallel',p.proparallel,
   'procost',p.procost,'prorows',p.prorows,'proargnames',p.proargnames,'proargmodes',p.proargmodes::text,
   'return_type',p.prorettype::regtype::text,'identity_arguments',pg_get_function_identity_arguments(p.oid),
   'arguments',pg_get_function_arguments(p.oid),'language',l.lanname) INTO actual
   FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=before_function.oid;
  IF actual IS DISTINCT FROM spec->'expected' THEN
   RAISE EXCEPTION 'auth_expiry_core_attributes_changed_requires_review: %',spec->>'signature'; END IF;
  IF md5(before_function.prosrc)=spec->>'after' THEN CONTINUE; END IF;
  IF (md5(before_function.prosrc) IS DISTINCT FROM spec->>'before'
      OR before_function.prosrc IS DISTINCT FROM spec->>'original')
   AND (md5(before_function.prosrc) IS DISTINCT FROM spec->>'canonicalBefore'
      OR before_function.prosrc IS DISTINCT FROM spec->>'canonicalOriginal') THEN
   RAISE EXCEPTION 'auth_expiry_core_body_changed_requires_review: %',spec->>'signature'; END IF;
  definition:=pg_get_functiondef(before_function.oid);
  IF strpos(definition,before_function.prosrc)=0 THEN RAISE EXCEPTION 'auth_expiry_exact_body_required'; END IF;
  EXECUTE replace(definition,before_function.prosrc,spec->>'patched');
  SELECT * INTO STRICT after_function FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(spec->>'signature');
  IF (to_jsonb(after_function)-'prosrc') IS DISTINCT FROM (to_jsonb(before_function)-'prosrc')
   OR md5(after_function.prosrc) IS DISTINCT FROM spec->>'after' THEN
   RAISE EXCEPTION 'auth_expiry_all_core_identity_attributes_must_remain_exact: %',spec->>'signature'; END IF;
 END LOOP;
END
